package ir.orix.school.classroom.api;
import java.time.LocalDate; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import ir.orix.school.classroom.application.ClassroomService; import ir.orix.school.classroom.domain.*; import ir.orix.school.shared.security.CurrentUser;
@RestController @RequestMapping("/api/v1/classroom")
public class ClassroomController {
 private final ClassroomService service; public ClassroomController(ClassroomService service){this.service=service;}
 @GetMapping @PreAuthorize("@scopeAuthorizer.hasTenantPermission('CLASS_READ')") public ClassroomService.Catalog catalog(){return service.catalog(CurrentUser.tenantId());}
 @PostMapping("/offerings") @PreAuthorize("@scopeAuthorizer.hasTenantPermission('CLASS_WRITE')") public ClassroomService.OfferingView offering(@Valid @RequestBody OfferingRequest r){return service.createOffering(CurrentUser.tenantId(),CurrentUser.accountId(),new ClassroomService.OfferingCommand(r.academicPeriodId(),r.courseId(),r.branchId(),r.code(),r.enrollmentStartsOn(),r.enrollmentEndsOn()));}
 @PostMapping("/sections") @PreAuthorize("@scopeAuthorizer.hasTenantPermission('CLASS_WRITE')") public ClassroomService.SectionView section(@Valid @RequestBody SectionRequest r){return service.createSection(CurrentUser.tenantId(),CurrentUser.accountId(),new ClassroomService.SectionCommand(r.offeringId(),r.code(),r.name(),r.capacity(),r.deliveryMode()));}
 @PostMapping("/instructors") @PreAuthorize("@scopeAuthorizer.hasTenantPermission('CLASS_WRITE')") public ClassroomService.InstructorView instructor(@Valid @RequestBody InstructorRequest r){return service.assignInstructor(CurrentUser.tenantId(),CurrentUser.accountId(),new ClassroomService.InstructorCommand(r.classSectionId(),r.instructorId(),r.role(),r.primary(),r.effectiveFrom(),r.effectiveTo()));}
 public record OfferingRequest(@NotNull Long academicPeriodId,@NotNull Long courseId,@NotNull Long branchId,@NotBlank @Size(max=60) String code,LocalDate enrollmentStartsOn,LocalDate enrollmentEndsOn){} public record SectionRequest(@NotNull Long offeringId,@NotBlank @Size(max=60) String code,@NotBlank @Size(max=200) String name,@Positive int capacity,@NotNull ClassSection.DeliveryMode deliveryMode){} public record InstructorRequest(@NotNull Long classSectionId,@NotNull Long instructorId,@NotNull ClassInstructor.Role role,boolean primary,@NotNull LocalDate effectiveFrom,LocalDate effectiveTo){}
}
